import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"60、【节】 兑下坎上","description":"横渠易说 - 60、【节】 兑下坎上","frontmatter":{"title":"60、【节】 兑下坎上","description":"横渠易说 - 60、【节】 兑下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/062.md","filePath":"zh/classics/hengqu/062.md"}'),l={name:"zh/classics/hengqu/062.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_60、【节】-兑下坎上" tabindex="-1">60、【节】 兑下坎上 <a class="header-anchor" href="#_60、【节】-兑下坎上" aria-label="Permalink to “60、【节】 兑下坎上”">​</a></h1><h3 id="彖曰-节亨-刚柔分而刚得中-苦节不可贞-其道穷也。说以行险-当位以节-中正以通。天地节而四时成-节以制度-不伤财-不害民。" tabindex="-1">彖曰：节亨，刚柔分而刚得中，“苦节不可贞”，其道穷也。说以行险，当位以节，中正以通。天地节而四时成，节以制度，不伤财，不害民。 <a class="header-anchor" href="#彖曰-节亨-刚柔分而刚得中-苦节不可贞-其道穷也。说以行险-当位以节-中正以通。天地节而四时成-节以制度-不伤财-不害民。" aria-label="Permalink to “彖曰：节亨，刚柔分而刚得中，“苦节不可贞”，其道穷也。说以行险，当位以节，中正以通。天地节而四时成，节以制度，不伤财，不害民。”">​</a></h3><h3 id="象曰-泽上有水-节-君子以制数度-议德行。" tabindex="-1">象曰：泽上有水，节，君子以制数度，议德行。 <a class="header-anchor" href="#象曰-泽上有水-节-君子以制数度-议德行。" aria-label="Permalink to “象曰：泽上有水，节，君子以制数度，议德行。”">​</a></h3><p>以苦节为贞，其道之穷必矣。</p><h3 id="初九-不出户庭-无咎。-象曰-不出户庭-知通塞也。" tabindex="-1">初九，不出户庭，无咎。 象曰：“不出户庭”，知通塞也。 <a class="header-anchor" href="#初九-不出户庭-无咎。-象曰-不出户庭-知通塞也。" aria-label="Permalink to “初九，不出户庭，无咎。 象曰：“不出户庭”，知通塞也。”">​</a></h3><p>见塞于九二，故不出。</p><h3 id="九二-不出门庭-凶。-象曰-不出门庭-凶-失时极也。" tabindex="-1">九二，不出门庭，凶。 象曰：“不出门庭，凶”，失时极也。 <a class="header-anchor" href="#九二-不出门庭-凶。-象曰-不出门庭-凶-失时极也。" aria-label="Permalink to “九二，不出门庭，凶。 象曰：“不出门庭，凶”，失时极也。”">​</a></h3><p>体柔位阴，故不出门庭凶。</p><h3 id="六三-不节若则嗟若-无咎。-象曰-不节之嗟-又谁咎也" tabindex="-1">六三，不节若则嗟若，无咎。 象曰：不节之嗟，又谁咎也! <a class="header-anchor" href="#六三-不节若则嗟若-无咎。-象曰-不节之嗟-又谁咎也" aria-label="Permalink to “六三，不节若则嗟若，无咎。 象曰：不节之嗟，又谁咎也!”">​</a></h3><p>处非其位，失节也，然能居不自安，则人将容之，故无咎。兑，说也，故能嗟咨取容。 王弼于此无咎又别立一例，只旧例亦可推行，但能嗟其不节有过之心则亦无咎也。若武帝下罪己之诏而天下悦，大人过既改，则复何咎之有!</p><h3 id="六四-安节-亨。-象曰-安节之亨-承上道也。" tabindex="-1">六四，安节，亨。 象曰：安节之亨，承上道也。 <a class="header-anchor" href="#六四-安节-亨。-象曰-安节之亨-承上道也。" aria-label="Permalink to “六四，安节，亨。 象曰：安节之亨，承上道也。”">​</a></h3><h3 id="九五-甘节-吉-往有尚。-象曰-甘节之吉-居位中也。" tabindex="-1">九五，甘节，吉，往有尚。 象曰：甘节之吉，居位中也。 <a class="header-anchor" href="#九五-甘节-吉-往有尚。-象曰-甘节之吉-居位中也。" aria-label="Permalink to “九五，甘节，吉，往有尚。 象曰：甘节之吉，居位中也。”">​</a></h3><p>以刚居中，得乎盛位，优为其节者也，守之不懈，富贵常保，故曰“往有尚”。</p><h3 id="上六-苦节-贞凶-悔亡。-象曰-苦节贞凶-其道穷也。" tabindex="-1">上六，苦节，贞凶，悔亡。 象曰：“苦节贞凶”，其道穷也。 <a class="header-anchor" href="#上六-苦节-贞凶-悔亡。-象曰-苦节贞凶-其道穷也。" aria-label="Permalink to “上六，苦节，贞凶，悔亡。 象曰：“苦节贞凶”，其道穷也。”">​</a></h3><p>处险之极，故曰“苦节”。苦节而不正，悔也，必正而凶，则道虽穷而悔亡；苦节反若获吉，取悔必多。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
